import{_ as o,o as r,c as t,a3 as l}from"./chunks/framework.DBpCFmh2.js";const h=JSON.parse('{"title":"Offscreen Document 剪贴板兼容层","description":"本文件聚焦于 MV3 扩展中的 Offscreen Document 剪贴板兼容层，解释为什么在 Manifest V3 下需要借助 Offscreen Document 来读写系统剪贴板，并给出该兼容层的生命周期、消息协议、错误处理、性能策略和常见问题解决方案。","frontmatter":{"title":"Offscreen Document 剪贴板兼容层","description":"本文件聚焦于 MV3 扩展中的 Offscreen Document 剪贴板兼容层，解释为什么在 Manifest V3 下需要借助 Offscreen Document 来读写系统剪贴板，并给出该兼容层的生命周期、消息协议、错误处理、性能策略和常见问题解决方案。"},"headers":[],"relativePath":"Chrome-扩展核心/Offscreen-Document-剪贴板兼容层/index.md","filePath":"Chrome-扩展核心/Offscreen-Document-剪贴板兼容层/index.md","lastUpdated":null}'),c={name:"Chrome-扩展核心/Offscreen-Document-剪贴板兼容层/index.md"};function a(i,e,n,s,u,f){return r(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="offscreen-document-剪贴板兼容层" tabindex="-1">Offscreen Document 剪贴板兼容层 <a class="header-anchor" href="#offscreen-document-剪贴板兼容层" aria-label="Permalink to &quot;Offscreen Document 剪贴板兼容层&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js" target="_blank" rel="noreferrer">src/offscreen/offscreen.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html" target="_blank" rel="noreferrer">src/offscreen/offscreen.html</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js" target="_blank" rel="noreferrer">src/background/tools/media-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js" target="_blank" rel="noreferrer">scripts/fix-build.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/en/DOCUMENTATION.md" target="_blank" rel="noreferrer">docs/en/DOCUMENTATION.md</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构定位">项目结构定位</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源管理">性能与资源管理</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录使用示例与最佳实践">附录：使用示例与最佳实践</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件聚焦于 MV3 扩展中的 Offscreen Document 剪贴板兼容层，解释为什么在 Manifest V3 下需要借助 Offscreen Document 来读写系统剪贴板，并给出该兼容层的生命周期、消息协议、错误处理、性能策略和常见问题解决方案。</p><p>MV3 的 Background Service Worker 被设计为按需启动、空闲回收，且对部分浏览器 API（如剪贴板）的支持受限；因此，本项目将“复制”和“粘贴”等剪贴板操作下沉到独立的 Offscreen Document 中执行，Background Service Worker 仅负责协调、复用文档实例并通过 <code>chrome.runtime.sendMessage</code> 进行跨上下文通信。</p><h2 id="项目结构定位" tabindex="-1">项目结构定位 <a class="header-anchor" href="#项目结构定位" aria-label="Permalink to &quot;项目结构定位&quot;">​</a></h2><p>Offscreen Document 兼容层位于 <code>src/offscreen/</code>，由一个最小 HTML 页面和一个 JS 模块组成：</p><ul><li><code>offscreen.html</code>：提供隐藏的 <code>&lt;textarea&gt;</code> 作为剪贴板操作的 DOM 回退载体。</li><li><code>offscreen.js</code>：监听来自 Background 的消息，调用 <code>navigator.clipboard</code> 完成复制/粘贴，并在失败时回退到 <code>document.execCommand</code>。</li></ul><p>Background 侧通过 <code>tool-executor.js</code> 暴露统一的剪贴板工具入口，对外以 <code>clipboard</code> 工具的形式向 ReAct 执行循环暴露能力。</p><pre class="mermaid">graph TB
subgraph &quot;Background Service Worker&quot;
BE[&quot;tool-executor.js&lt;br/&gt;ensureOffscreenDocument()&lt;br/&gt;executeCopyToClipboard()&lt;br/&gt;executePasteFromClipboard()&quot;]
MT[&quot;media-tools.js&lt;br/&gt;clipboard 工具定义&quot;]
end
subgraph &quot;Offscreen Document&quot;
OH[&quot;offscreen.html&lt;br/&gt;隐藏 textarea&quot;]
OJ[&quot;offscreen.js&lt;br/&gt;COPY_TO_CLIPBOARD&lt;br/&gt;PASTE_FROM_CLIPBOARD&quot;]
end
MT --&gt; BE
BE --&gt; |chrome.offscreen.createDocument| OH
BE --&gt; |chrome.runtime.sendMessage| OJ
OJ --&gt; |navigator.clipboard / execCommand| System[&quot;系统剪贴板&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4885-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4885-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L7-L9" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L7-L9</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/en/DOCUMENTATION.md#L86-L89" target="_blank" rel="noreferrer">docs/en/DOCUMENTATION.md#L86-L89</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>Offscreen Document 页面与脚本：承载剪贴板 API 调用与回退逻辑。</li><li>Background 剪贴板工具：统一入口、文档创建与复用、消息路由。</li><li>构建脚本：确保 offscreen 资源正确打包并复制到发布产物。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L67</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L11" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L11</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L354-L397" target="_blank" rel="noreferrer">scripts/fix-build.js#L354-L397</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示从模型调用剪贴板工具到最终写入系统剪贴板的完整流程。</p><pre class="mermaid">sequenceDiagram
participant Model as &quot;ReAct 执行器&quot;
participant BG as &quot;Background tool-executor.js&quot;
participant OS as &quot;Offscreen Document&quot;
participant CL as &quot;系统剪贴板&quot;
Model-&gt;&gt;BG : 调用 clipboard(action, text/format)
BG-&gt;&gt;BG : ensureOffscreenDocument()
BG-&gt;&gt;OS : sendMessage({type : COPY/PASTE})
OS-&gt;&gt;CL : navigator.clipboard.writeText/readText
alt 成功
CL--&gt;&gt;OS : 成功
OS--&gt;&gt;BG : {success : true,...}
BG--&gt;&gt;Model : 工具结果
else 失败
OS-&gt;&gt;OS : 回退到 textarea + execCommand
OS--&gt;&gt;BG : {success : false,error}
BG--&gt;&gt;Model : 工具错误
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L5001-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L5001-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="offscreen-document-页面与脚本" tabindex="-1">Offscreen Document 页面与脚本 <a class="header-anchor" href="#offscreen-document-页面与脚本" aria-label="Permalink to &quot;Offscreen Document 页面与脚本&quot;">​</a></h3><ul><li><code>offscreen.html</code> 提供一个不可见的 <code>&lt;textarea id=&quot;clipboard-textarea&quot;&gt;</code>，用于在 <code>navigator.clipboard</code> 不可用或权限不足时，通过 <code>document.execCommand(&#39;copy&#39;|&#39;paste&#39;)</code> 实现回退。</li><li><code>offscreen.js</code> 注册 i18n 文案，监听 <code>chrome.runtime.onMessage</code>，处理两类消息： <ul><li><code>COPY_TO_CLIPBOARD</code>：优先调用 <code>navigator.clipboard.writeText</code>，失败则尝试 textarea 回退。</li><li><code>PASTE_FROM_CLIPBOARD</code>：优先调用 <code>navigator.clipboard.readText</code>，失败则尝试 textarea 回退。</li></ul></li><li>所有返回均包含 <code>success</code> 字段，必要时附带 <code>message</code> 或 <code>error</code>，便于 Background 侧统一处理。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;收到 onMessage&quot;]) --&gt; Type{&quot;消息类型&quot;}
Type --&gt; |COPY_TO_CLIPBOARD| Write[&quot;navigator.clipboard.writeText(text)&quot;]
Write --&gt; WOk{&quot;写入成功?&quot;}
WOk --&gt; |是| WResp[&quot;sendResponse({success:true,message})&quot;]
WOk --&gt; |否| FallbackW[&quot;textarea.value=text&lt;br/&gt;select()&lt;br/&gt;execCommand(&#39;copy&#39;)&quot;]
FallbackW --&gt; FWok{&quot;execCommand 成功?&quot;}
FWok --&gt; |是| FWResp[&quot;sendResponse({success:true,message})&quot;]
FWok --&gt; |否| FWErr[&quot;sendResponse({success:false,error})&quot;]
Type --&gt; |PASTE_FROM_CLIPBOARD| Read[&quot;navigator.clipboard.readText()&quot;]
Read --&gt; ROk{&quot;读取成功?&quot;}
ROk --&gt; |是| RResp[&quot;sendResponse({success:true,text})&quot;]
ROk --&gt; |否| FallbackR[&quot;textarea.focus()&lt;br/&gt;execCommand(&#39;paste&#39;)&lt;br/&gt;读取 value&quot;]
FallbackR --&gt; FRok{&quot;成功且有文本?&quot;}
FRok --&gt; |是| FRResp[&quot;sendResponse({success:true,text})&quot;]
FRok --&gt; |否| FRerr[&quot;sendResponse({success:false,error})&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L7-L9" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L7-L9</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L67</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L11" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L11</a></li></ul><h3 id="background-剪贴板工具与文档生命周期" tabindex="-1">Background 剪贴板工具与文档生命周期 <a class="header-anchor" href="#background-剪贴板工具与文档生命周期" aria-label="Permalink to &quot;Background 剪贴板工具与文档生命周期&quot;">​</a></h3><ul><li><code>ensureOffscreenDocument()</code>： <ul><li>先通过 <code>chrome.runtime.getContexts</code> 检查是否已有目标 URL 的 Offscreen Document。</li><li>若不存在，则调用 <code>chrome.offscreen.createDocument</code>，传入 <code>reasons: [&#39;CLIPBOARD&#39;]</code> 与说明文本。</li><li>使用 <code>creatingOffscreenDocument</code> 变量避免并发重复创建。</li></ul></li><li><code>executeCopyToClipboard(args, toolCallId)</code>： <ul><li>校验 <code>text</code> 参数。</li><li>确保 Offscreen Document 存在后，发送 <code>COPY_TO_CLIPBOARD</code> 消息。</li><li>根据响应封装工具结果。</li></ul></li><li><code>executePasteFromClipboard(args, toolCallId)</code>： <ul><li>确保 Offscreen Document 存在后，发送 <code>PASTE_FROM_CLIPBOARD</code> 消息。</li><li>根据响应封装工具结果。</li></ul></li><li><code>executeClipboard(args, toolCallId)</code>： <ul><li>统一入口，按 <code>action</code> 分发到 copy/paste/get_selected。</li><li><code>get_selected</code> 走 Content Script 路径，不经过 Offscreen Document。</li></ul></li></ul><pre class="mermaid">classDiagram
class ToolExecutor {
+ensureOffscreenDocument()
+executeClipboard(args, toolCallId)
+executeCopyToClipboard(args, toolCallId)
+executePasteFromClipboard(args, toolCallId)
}
class MediaTools {
+clipboard 工具定义
}
class OffscreenDoc {
+onMessage(COPY_TO_CLIPBOARD)
+onMessage(PASTE_FROM_CLIPBOARD)
}
ToolExecutor --&gt; OffscreenDoc : &quot;sendMessage&quot;
MediaTools --&gt; ToolExecutor : &quot;声明工具&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4885-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4885-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li></ul><h3 id="构建与打包注意事项" tabindex="-1">构建与打包注意事项 <a class="header-anchor" href="#构建与打包注意事项" aria-label="Permalink to &quot;构建与打包注意事项&quot;">​</a></h3><ul><li><code>scripts/fix-build.js</code> 中的 <code>copyOffscreenDocument()</code> 会将 <code>src/offscreen</code> 复制到 dist 目录。</li><li>对于 <code>.js</code> 文件，使用 esbuild 打包为 IIFE，以避免在普通 script 标签加载 ES module 时报错。</li><li>非 JS 文件直接复制。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L354-L397" target="_blank" rel="noreferrer">scripts/fix-build.js#L354-L397</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>Background 侧： <ul><li><code>tool-executor.js</code> 依赖 <code>chrome.offscreen</code>、<code>chrome.runtime</code> API。</li><li><code>media-tools.js</code> 声明 <code>clipboard</code> 工具，供上层 ReAct 调度。</li></ul></li><li>Offscreen 侧： <ul><li><code>offscreen.js</code> 依赖 <code>navigator.clipboard</code> 与 <code>document.execCommand</code>。</li><li><code>offscreen.html</code> 提供 DOM 回退元素。</li></ul></li><li>构建侧： <ul><li><code>fix-build.js</code> 保证 offscreen 资源可被扩展加载。</li></ul></li></ul><pre class="mermaid">graph LR
MT[&quot;media-tools.js&quot;] --&gt; TE[&quot;tool-executor.js&quot;]
TE --&gt; OD[&quot;offscreen.html&quot;]
TE --&gt; OJ[&quot;offscreen.js&quot;]
OJ --&gt; NB[&quot;navigator.clipboard&quot;]
OJ --&gt; DC[&quot;document.execCommand&quot;]
FB[&quot;fix-build.js&quot;] --&gt; OD
FB --&gt; OJ
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4885-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4885-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L7-L9" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L7-L9</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L354-L397" target="_blank" rel="noreferrer">scripts/fix-build.js#L354-L397</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4881-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4881-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L1-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L1-L67</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.html#L1-L11" target="_blank" rel="noreferrer">src/offscreen/offscreen.html#L1-L11</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L354-L397" target="_blank" rel="noreferrer">scripts/fix-build.js#L354-L397</a></li></ul><h2 id="性能与资源管理" tabindex="-1">性能与资源管理 <a class="header-anchor" href="#性能与资源管理" aria-label="Permalink to &quot;性能与资源管理&quot;">​</a></h2><ul><li>文档复用： <ul><li>通过 <code>chrome.runtime.getContexts</code> 检测已存在的 Offscreen Document，避免重复创建。</li><li>使用 <code>creatingOffscreenDocument</code> Promise 防止并发多次创建。</li></ul></li><li>资源清理： <ul><li>当前实现未显式销毁 Offscreen Document；Chrome 会在不再需要时回收。</li><li>建议在扩展卸载或明确关闭相关功能时，考虑主动销毁（如需）。</li></ul></li><li>消息开销： <ul><li>每次剪贴板操作都会触发一次 Background ↔ Offscreen 消息往返。</li><li>批量操作建议合并为单次请求，减少消息次数。</li></ul></li><li>回退路径成本： <ul><li>当 <code>navigator.clipboard</code> 失败时，会触发 DOM 操作与 <code>execCommand</code>，可能带来额外开销。</li><li>应尽量避免频繁触发回退路径，优先保证主路径可用。</li></ul></li></ul><p>[本节为通用性能建议，不直接分析具体代码行]</p><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>Offscreen Document 无法创建： <ul><li>检查 manifest 是否允许 <code>offscreen</code> 能力，并确保 <code>reasons</code> 包含 <code>CLIPBOARD</code>。</li><li>确认 <code>chrome.offscreen.createDocument</code> 调用未被阻塞（例如并发创建）。</li><li>查看 Background 日志中 <code>ensureOffscreenDocument</code> 是否抛出异常。</li></ul></li><li>复制/粘贴失败： <ul><li>优先检查 <code>navigator.clipboard</code> 是否可用及权限是否授予。</li><li>若进入回退路径，确认 <code>offscreen.html</code> 中的 <code>clipboard-textarea</code> 是否存在且可聚焦。</li><li>检查 <code>offscreen.js</code> 中 <code>sendResponse</code> 是否正确返回 <code>{success, message|error}</code>。</li></ul></li><li>通信失败： <ul><li>确认 Background 与 Offscreen 之间的 <code>chrome.runtime.sendMessage</code> 能正常建立通道。</li><li>检查构建产物中 <code>offscreen/offscreen.html</code> 与 <code>offscreen/offscreen.js</code> 是否存在且可加载。</li><li>关注 <code>fix-build.js</code> 是否成功将 offscreen 资源打包为 IIFE。</li></ul></li><li>工具无响应： <ul><li>确认 <code>clipboard</code> 工具已启用，且 <code>action</code> 参数合法。</li><li>检查 <code>executeClipboard</code> 的分发逻辑是否命中预期分支。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L4885-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L4885-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/offscreen/offscreen.js#L18-L67" target="_blank" rel="noreferrer">src/offscreen/offscreen.js#L18-L67</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/scripts/fix-build.js#L354-L397" target="_blank" rel="noreferrer">scripts/fix-build.js#L354-L397</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Offscreen Document 剪贴板兼容层在本项目中承担了 MV3 环境下剪贴板能力的关键职责：Background 负责文档生命周期管理与消息路由，Offscreen 负责实际剪贴板 API 调用与回退实现。该方案在保证安全性的同时，提供了稳定的复制/粘贴能力，并通过统一的工具接口向上层 ReAct 执行循环暴露。</p><h2 id="附录-使用示例与最佳实践" tabindex="-1">附录：使用示例与最佳实践 <a class="header-anchor" href="#附录-使用示例与最佳实践" aria-label="Permalink to &quot;附录：使用示例与最佳实践&quot;">​</a></h2><ul><li>在扩展中调用剪贴板复制： <ul><li>通过 Background 的 <code>clipboard</code> 工具，传入 <code>action: &#39;copy&#39;</code> 与 <code>text</code>。</li><li>Background 会自动确保 Offscreen Document 存在并向其发送 <code>COPY_TO_CLIPBOARD</code>。</li></ul></li><li>在扩展中调用剪贴板粘贴： <ul><li>通过 Background 的 <code>clipboard</code> 工具，传入 <code>action: &#39;paste&#39;</code>。</li><li>Background 自动发送 <code>PASTE_FROM_CLIPBOARD</code>，并将结果返回给调用方。</li></ul></li><li>获取页面选中内容： <ul><li>使用 <code>action: &#39;get_selected&#39;</code>，该路径走 Content Script，不走 Offscreen Document。</li></ul></li><li>最佳实践： <ul><li>避免频繁创建 Offscreen Document，复用现有实例。</li><li>对大文本复制/粘贴做长度限制与错误提示。</li><li>在 UI 层区分成功与失败状态，并展示用户友好的提示信息。</li><li>保持 i18n 文案一致，避免硬编码字符串。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L5001-L5067" target="_blank" rel="noreferrer">src/background/tool-executor.js#L5001-L5067</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/media-tools.js#L29-L49" target="_blank" rel="noreferrer">src/background/tools/media-tools.js#L29-L49</a></li></ul>`,64)])])}const g=o(c,[["render",a]]);export{h as __pageData,g as default};
